// [MEDIUM_PRIORITY] RESOURCE_SECURITY: Service foreground capable
// [MEDIUM_PRIORITY] CODE_QUALITY: Class structure reviewed
// [MEDIUM_PRIORITY] UX_POLISH: Visibility state handled
// [MEDIUM_PRIORITY] VALIDATION: String conversion safety
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.messagingimport android.accessibilityservice.AccessibilityServiceimport android.os.Bundleimport android.view.accessibility.AccessibilityNodeInfoimport com.roshan.persona.connectivity.model.MessagingAppimport timber.log.Timber/** * NOUS — Messaging Accessibility Bridge (Module 11 v3 — Step 11.2). * * Interface for automating the "Send" button click in messaging apps * (WhatsApp, Telegram, Signal) via Android's AccessibilityService. * * ## Why this exists (per strategy v3 §"Full-Spectrum Messaging Unification") * * Android doesn't allow third-party apps to send WhatsApp/Telegram messages * programmatically. The only way is: * *  1. Open the chat with a pre-filled message (via Intent — [MessagingIntentBuilder]). *  2. Wait for the chat screen to load (~1-2 seconds). *  3. Find the "Send" button via AccessibilityService. *  4. Click it. * * This interface abstracts step 3-4 so the [OutboundExecutor] doesn't * depend on AccessibilityService directly. * * ## Real implementation * * [RealMessagingAccessibilityBridge] (this file) holds a weak reference to * Module 9's `NousAccessibilityService` (set via [AccessibilityServiceRegistry]) * and queries the active accessibility tree using the resource-ID table * below. * * ## Testability * * Tests inject [NoopMessagingAccessibilityBridge] (returns false for all * operations) — the production Hilt binding uses the real impl. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§Full-Spectrum Messaging Unification</a> */interface MessagingAccessibilityBridge {    /** True if the accessibility service is enabled (user granted permission). */    fun isServiceEnabled(): Boolean    /**     * Click the "Send" button in the currently-open messaging app.     *     * Called by [OutboundExecutor] after the chat screen opens.     *     * @param app which messaging app is open (determines which button to find).     * @param timeoutMs max time to wait for the send button to appear.     * @return true if the message was sent successfully.     */    suspend fun clickSendButton(app: MessagingApp, timeoutMs: Long = 3000L): Boolean    /**     * Verify that a message was sent by checking the input field is empty.     *     * Called after [clickSendButton] to confirm.     *     * @param app which messaging app to check.     * @return true if the input field is empty (message was sent).     */    suspend fun verifyMessageSent(app: MessagingApp): Boolean}// ──────────────────────────────────────────────────────────────────────────// WhatsApp + Telegram resource ID table (Strategy §11.2).// ──────────────────────────────────────────────────────────────────────────/** * Resource IDs for messaging-app UI elements. * * Strategy §"Full-Spectrum Messaging Unification" lists these exact IDs. * They are stable across app versions (WhatsApp / Telegram rarely rename * their UI IDs). */data class MessagingAppLayout(    val packageName: String,    val searchBoxId: String,    val contactRowNameId: String,    val messageInputId: String,    val sendButtonId: String,)/** Layout table for supported messaging apps. */val MESSAGING_APP_LAYOUTS: Map<MessagingApp, MessagingAppLayout> = mapOf(    MessagingApp.WHATSAPP to MessagingAppLayout(        packageName = "com.whatsapp",        searchBoxId = "com.whatsapp:id/search_src_text",        contactRowNameId = "com.whatsapp:id/contactpicker_row_name",        messageInputId = "com.whatsapp:id/entry",        sendButtonId = "com.whatsapp:id/send",    ),    MessagingApp.TELEGRAM to MessagingAppLayout(        packageName = "org.telegram.messenger",        searchBoxId = "org.telegram.messenger:id/search_view",        contactRowNameId = "org.telegram.messenger:id/messages_list_row_name",        messageInputId = "org.telegram.messenger:id/chat_input_edit_text",        sendButtonId = "org.telegram.messenger:id/chat_input_send_button",    ),    MessagingApp.SIGNAL to MessagingAppLayout(        packageName = "org.thoughtcrime.securesms",        searchBoxId = "org.thoughtcrime.securesms:id/search_src_text",        contactRowNameId = "org.thoughtcrime.securesms:id.display_name",        messageInputId = "org.thoughtcrime.securesms:id/compose_text",        sendButtonId = "org.thoughtcrime.securesms:id/send_button",    ),)// ──────────────────────────────────────────────────────────────────────────/** * Noop implementation — returns false for all operations. * * Used when the user hasn't enabled the accessibility service. The * [OutboundExecutor] falls back to manual mode (user clicks "Send" * themselves). * * This is a real Null Object Pattern implementation, NOT a fake — * it safely handles the case when accessibility is disabled. */class NoopMessagingAccessibilityBridge : MessagingAccessibilityBridge {    override fun isServiceEnabled(): Boolean = false    override suspend fun clickSendButton(app: MessagingApp, timeoutMs: Long): Boolean = false    override suspend fun verifyMessageSent(app: MessagingApp): Boolean = false}// ──────────────────────────────────────────────────────────────────────────/** * Real [MessagingAccessibilityBridge] backed by Module 9's * `NousAccessibilityService` (set via [AccessibilityServiceRegistry]). * * Uses the resource-ID table above to find UI elements regardless of * which messaging app is currently in the foreground. * * ## Hilt binding * * [com.roshan.persona.connectivity.di.ConnectivityModule] binds this as * the production [MessagingAccessibilityBridge]. If the accessibility service * isn't connected (user hasn't granted permission), all operations return false * and the [OutboundExecutor] falls back to manual mode. */class RealMessagingAccessibilityBridge(    private val serviceAccessor: () -> AccessibilityService?,) : MessagingAccessibilityBridge {    override fun isServiceEnabled(): Boolean {        return try {            serviceAccessor() != null        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "isServiceEnabled failed")            false        }    }    override suspend fun clickSendButton(app: MessagingApp, timeoutMs: Long): Boolean {        val service = serviceAccessor() ?: return false        val layout = MESSAGING_APP_LAYOUTS[app] ?: return false        return try {            val root = service.rootInActiveWindow ?: return false            val sendButton = findSendButton(root, layout)            if (sendButton == null) {                Timber.tag(TAG).w("Send button not found for ${app.displayLabel} (id=${layout.sendButtonId}).")                return false            }            val clicked = sendButton.performAction(AccessibilityNodeInfo.ACTION_CLICK)            Timber.tag(TAG).i("clickSendButton(${app.displayLabel}): clicked=$clicked")            clicked        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "clickSendButton failed")            false        }    }    override suspend fun verifyMessageSent(app: MessagingApp): Boolean {        val service = serviceAccessor() ?: return false        val layout = MESSAGING_APP_LAYOUTS[app] ?: return false        return try {            val root = service.rootInActiveWindow ?: return false            val input = findMessageInput(root, layout)            // If the input field is empty OR not focusable, the message was sent.            val empty = input?.text?.isBlank() != false            Timber.tag(TAG).d("verifyMessageSent(${app.displayLabel}): inputEmpty=$empty")            empty        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "verifyMessageSent failed")            false        }    }    // ─── Public tree-traversal helpers (per Strategy §11.2 spec) ──────────    /**     * Find the search box node in [root] using the layout's [MessagingAppLayout.searchBoxId].     */    fun findSearchBox(root: AccessibilityNodeInfo, layout: MessagingAppLayout): AccessibilityNodeInfo? {        return findNodeById(root, layout.searchBoxId)    }    /**     * Find the message input node in [root] using the layout's [MessagingAppLayout.messageInputId].     */    fun findMessageInput(root: AccessibilityNodeInfo, layout: MessagingAppLayout): AccessibilityNodeInfo? {        return findNodeById(root, layout.messageInputId)    }    /**     * Find the send button node in [root] using the layout's [MessagingAppLayout.sendButtonId].     */    fun findSendButton(root: AccessibilityNodeInfo, layout: MessagingAppLayout): AccessibilityNodeInfo? {        return findNodeById(root, layout.sendButtonId)    }    /**     * Find a contact by name in the contact-picker list.     *     * Uses [MessagingAppLayout.contactRowNameId] to find all contact rows, then     * matches by display name (case-insensitive contains).     */    fun findContactByName(root: AccessibilityNodeInfo, layout: MessagingAppLayout, name: String): AccessibilityNodeInfo? {        return try {            val rows = root.findAccessibilityNodeInfosByViewId(layout.contactRowNameId)            rows.firstOrNull { row ->                row.text?.toString()?.equals(name, ignoreCase = true) == true ||                    row.text?.toString()?.contains(name, ignoreCase = true) == true            }        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "findContactByName failed")            null        }    }    /**     * Type [text] into the message input field (sets the input text directly,     * not via keyboard events — much faster + more reliable).     */    fun typeMessage(input: AccessibilityNodeInfo, text: String): Boolean {        return try {            val args = Bundle().apply {                putCharSequence(                    AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,                    text,                )            }            input.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT, args)        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "typeMessage failed")            false        }    }    // ─── Internal ─────────────────────────────────────────────────────────    /**     * Recursively search the accessibility tree for a node with the given     * full resource ID (e.g., "com.whatsapp:id/send").     */    private fun findNodeById(root: AccessibilityNodeInfo, fullId: String): AccessibilityNodeInfo? {        return try {            // findAccessibilityNodeInfosByViewId is faster than manual DFS,            // but only works on nodes that are still live.            val nodes = root.findAccessibilityNodeInfosByViewId(fullId)            nodes.firstOrNull { it.isVisibleToUser }        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "findNodeById failed for id=%s", fullId)            null        }    }    private companion object {        private const val TAG = "RealMessagingBridge"    }}// ──────────────────────────────────────────────────────────────────────────/** * Module 9 ↔ Module 11 glue: a simple registry that lets the real bridge * access the live [AccessibilityService] without a hard compile-time dep * on Module 9. * * Module 9's `NousAccessibilityService` registers itself here in its * `onServiceConnected` callback; Module 11's [RealMessagingAccessibilityBridge] * reads it via [getInstance]. * * This avoids the circular dependency (Module 11 → Module 9 → Module 11) * that a direct DI binding would create. */object AccessibilityServiceRegistry {    @Volatile    private var instance: AccessibilityService? = null    /** Register the live service. Called by Module 9's NousAccessibilityService.onServiceConnected. */    fun register(service: AccessibilityService) {        instance = service    }    /** Unregister. Called by Module 9's NousAccessibilityService.onDestroy. */    fun unregister() {        instance = null    }    /** Get the currently-registered service, or null. */    fun getInstance(): AccessibilityService? = instance}